import React, { useContext, useState, useEffect } from "react";
import { AppContext } from "../../context/AppContext";
import { fetchBudget, updateBudget } from "../../utils/budget-utils";

const Budget = () => {
  const { budget, setBudget } = useContext(AppContext);
  const [inputBudget, setInputBudget] = useState(budget.toString());

  // Fetch budget on component mount
  useEffect(() => {
    loadBudget();
  }, []);

  const loadBudget = async () => {
    try {
      const fetchedBudget = await fetchBudget();
      setBudget(fetchedBudget);
      setInputBudget(fetchedBudget.toString()); // Initialize input with fetched budget
    } catch (err: any) {
      console.log(err.message);
    }
  };

  const handleBudgetUpdate = (newBudget: string) => {
    setInputBudget(newBudget);
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    
    const updatedBudget = parseInt(inputBudget);
    if (!isNaN(updatedBudget)) {
      try {
        await updateBudget(updatedBudget);
        setBudget(updatedBudget); // Update context after successful save
      } catch (err: any) {
        console.log(err.message);
      }
    }
  };

  return (
    <div className="p-3">
      <div className="alert alert-secondary mt-3">Budget: ${budget}</div>
      <form onSubmit={onSubmit} className="d-flex align-items-center">
        <input
          type="number"
          value={inputBudget}
          onChange={(e) => handleBudgetUpdate(e.target.value)}
          className="form-control me-2"
        />
        <button type="submit" className="btn btn-primary">
          Save
        </button>
      </form>
    </div>
  );
};

export default Budget;
